import {
  Group,
  Mesh,
  PlaneGeometry,
  BoxGeometry,
  Texture,
  Color,
  PointLight,
  DoubleSide,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
  SRGBColorSpace,
} from 'three/webgpu';
import {
  texture,
  uniform,
  positionLocal,
  normalLocal,
  uv,
  mix,
  length,
  smoothstep,
  vec3,
} from 'three/tsl';
import { gsap } from 'gsap';

const INK = '#16161d';
const PAPER = '#e8ecf2';
const ACCENT = '#ff2a38';
const SURFACE = '#0b0b10';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();
  root.name = 'home-quote-panel';

  const inner = new Group();
  root.add(inner);

  const cleanupFns = [];
  const timelines = [];

  // ---- dimensions from atlas rect (512x320 -> preserve aspect) ----
  const aspect = 512 / 320;
  const cardHeight = 1.7;
  const cardWidth = cardHeight * aspect;

  // ---- placeholder textures, swapped in-place once loaded ----
  const colorTex = new Texture();
  const depthTex = new Texture();
  const colorNode = texture(colorTex);
  const depthNode = texture(depthTex);

  const dispScale = uniform(0.1);

  const cardMat = new MeshPhysicalNodeMaterial({
    side: DoubleSide,
    metalness: 0.42,
    roughness: 0.56,
    clearcoat: 0.18,
    clearcoatRoughness: 0.35,
  });
  cardMat.colorNode = colorNode;
  cardMat.positionNode = positionLocal.add(
    normalLocal.mul(depthNode.r.mul(dispScale))
  );

  const cardGeo = new PlaneGeometry(cardWidth, cardHeight, 64, 64);
  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.z = 0.06;
  inner.add(cardMesh);

  // load real textures asynchronously (sync-returning API; async fill-in)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      colorTex.image = tex.image;
      colorTex.colorSpace = SRGBColorSpace;
      colorTex.needsUpdate = true;
      cardMat.needsUpdate = true;
    });
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTex.image = tex.image;
      depthTex.needsUpdate = true;
      cardMat.needsUpdate = true;
    });
  }

  // ---- machined-metal bezel frame (backing plate, gradient ink->surface) ----
  const frameGeo = new BoxGeometry(cardWidth + 0.16, cardHeight + 0.16, 0.08);
  const frameMat = new MeshPhysicalNodeMaterial({
    metalness: 0.5,
    roughness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  frameMat.colorNode = mix(vec3(new Color(INK)), vec3(new Color(SURFACE)), uv().y);
  const frameMesh = new Mesh(frameGeo, frameMat);
  frameMesh.position.z = -0.02;
  inner.add(frameMesh);

  // ---- accent rim/back light (local, capped intensity) ----
  const rimLight = new PointLight(new Color(ACCENT), 1.1, 6, 2);
  rimLight.position.set(-cardWidth * 0.6, cardHeight * 0.4, -1.2);
  inner.add(rimLight);

  // ---- radial contact shadow beneath the panel ----
  const shadowRadius = cardWidth * 0.7;
  const shadowGeo = new PlaneGeometry(shadowRadius * 2, shadowRadius * 2, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const suv = uv().sub(0.5);
  const dist = length(suv).mul(2.0);
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = smoothstep(1.0, 0.0, dist).mul(0.5);
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -cardHeight * 0.62, 0.02);
  inner.add(shadowMesh);

  // ---- text: quote + attribution, rendered only if actual copy is provided ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textNodes = [];
  items.forEach((item, idx) => {
    if (!item || !item.text) return;
    const role = (item.role || '').toLowerCase();
    const isAttribution = role.includes('attrib') || role.includes('caption') || idx === 1;
    if (isAttribution) {
      const t = ctx.fontAtlas.createText(item.text.toUpperCase(), {
        fontSize: item.typography?.fontSize ?? 16,
        color: ACCENT,
        align: 'left',
        maxWidthPx: cardWidth * 340,
        letterSpacingPx: 1.4,
      });
      t.position.set(-cardWidth * 0.42, -cardHeight * 0.36, 0.09);
      inner.add(t);
      textNodes.push(t);
    } else {
      const t = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize ?? 32,
        color: PAPER,
        align: 'left',
        maxWidthPx: cardWidth * 360,
      });
      t.position.set(-cardWidth * 0.42, cardHeight * 0.18, 0.09);
      inner.add(t);
      textNodes.push(t);
    }
  });

  // ---- entrance: weighted-settle ----
  inner.scale.set(0.96, 0.96, 0.96);
  const baseY = 0;
  inner.position.y = baseY - 0.12;
  const entranceTl = gsap.timeline();
  entranceTl.to(inner.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  }, 0);
  entranceTl.to(inner.position, {
    y: baseY,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  timelines.push(entranceTl);

  // ---- cinematic primitives (delegated) ----
  const parallaxResult = ctx.primitives['parallax-scroll'](inner, { intensity: 0.4 });
  const depthRotateResult = ctx.primitives['depth-rotate'](cardMesh, { maxDeg: 8 });
  cleanupFns.push(() => parallaxResult?.cleanup?.());
  cleanupFns.push(() => depthRotateResult?.cleanup?.());

  // ---- interaction handlers ----
  let hoverTl = null;
  const handlePointerEnter = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.to(inner.position, {
      y: baseY + 0.15,
      duration: 0.3,
      ease: 'power2.out',
    });
    timelines.push(hoverTl);
  };
  const handlePointerLeave = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.to(inner.position, {
      y: baseY,
      duration: 0.3,
      ease: 'power2.out',
    });
    timelines.push(hoverTl);
  };
  const handleClick = () => {
    const pressTl = gsap.timeline();
    pressTl.to(inner.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(2)',
    }).to(inner.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.25,
      ease: 'power2.out',
    });
    timelines.push(pressTl);
    ctx.emit('hub-home.select', { nodeId: 'home-quote' });
  };

  root.userData.handlers = {
    pointerenter: handlePointerEnter,
    pointerleave: handlePointerLeave,
    click: handleClick,
  };

  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    cleanupFns.forEach((fn) => fn());
    textNodes.forEach((t) => t.parent && t.parent.remove(t));

    cardGeo.dispose();
    cardMat.dispose();
    frameGeo.dispose();
    frameMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    colorTex.dispose();
    depthTex.dispose();
    rimLight.dispose?.();
  };

  return root;
}
